INSERT INTO `v1_26a05860e4d3281177856ff5981d6586ea4843496757a5a6897420e3531ccf94` VALUES (0.890625, 1, 0.8828125, "ツムギのキーホルダーサイズのタペストリー。どこにでも飾れる\nうえに、身につけてお出掛けもできてしまう万能な一品。", 4, "ツムギのミニタペストリー", 11701);
